INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Code-Kommentare für jeden Code nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Klarer Code kann reichen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Code-Kommentaren?', 3, '[{"text": "Wartbarkeit", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Performance", "correct": false, "because": "Kein Einfluss"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu guten Kommentaren?', 5, '[{"text": "Warum-Erklärung", "correct": true, "because": "Begründet Logik"}, {"text": "Kürze", "correct": true, "because": "Klar und prägnant"}, {"text": "Code-Wiederholung", "correct": false, "because": "Redundant"}, {"text": "Persönliche Notizen", "correct": false, "because": "Nicht teamrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kommentare erklären komplexe Logik. b) Sie ersetzen Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Code-Kommentaren?', 4, '[{"text": "Klarheit", "correct": false, "because": "Essenziell für Lesbarkeit"}, {"text": "Kontext", "correct": false, "because": "Gibt Sinn"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant im Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kommentare immer aktuell bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Code ändert sich oft"}, {"text": "Ja", "correct": false, "because": "Pflege nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art Kommentar ist am nützlichsten?', 3, '[{"text": "Warum-Kommentar", "correct": true, "because": "Erklärt Entscheidungen"}, {"text": "Was-Kommentar", "correct": false, "because": "Code zeigt das oft"}, {"text": "Wer-Kommentar", "correct": false, "because": "Versionierung reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Kommentare effektiv?', 5, '[{"text": "Relevanz", "correct": true, "because": "Fokus auf Wichtiges"}, {"text": "Aktualität", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Länge", "correct": false, "because": "Kürze besser"}, {"text": "Farben", "correct": false, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kommentare sind nur für Anfänger. b) Profis brauchen sie nicht. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Alle profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht exklusiv"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht in einem Kommentar?', 4, '[{"text": "Kontext", "correct": false, "because": "Gibt Sinn"}, {"text": "Zweck", "correct": false, "because": "Erklärt Absicht"}, {"text": "Code-Duplikat", "correct": true, "because": "Redundant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Kommentare nur für komplexen Code?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfacher Code profitiert"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen gehören in Kommentare?', 4, '[{"text": "Absicht", "correct": true, "because": "Erklärt Warum"}, {"text": "Annahmen", "correct": true, "because": "Klärt Bedingungen"}, {"text": "Autorname", "correct": false, "because": "Git reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kommentare den Code verlangsamen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wird nicht ausgeführt"}, {"text": "Ja", "correct": false, "because": "Technisch falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Kommentaren?', 3, '[{"text": "Nützlichkeit", "correct": true, "because": "Hilft Entwicklern"}, {"text": "Menge", "correct": false, "because": "Qualität zählt"}, {"text": "Formatierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kommentare müssen präzise sein. b) Sie ersetzen Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben schlechte Kommentare?', 5, '[{"text": "Verwirrung", "correct": true, "because": "Falsche Infos"}, {"text": "Veraltet", "correct": true, "because": "Nicht gepflegt"}, {"text": "Hohe Leistung", "correct": false, "because": "Kein Nachteil"}, {"text": "Kürze", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Kommentaren unwichtig?', 3, '[{"text": "Klarheit", "correct": false, "because": "Essenziell"}, {"text": "Relevanz", "correct": false, "because": "Muss nützlich sein"}, {"text": "Zeilenlänge", "correct": true, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Kommentare sauberen Code?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Ja", "correct": false, "because": "Code bleibt primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kommentare für Solo-Projekte nötig sind?', 2, '[{"text": "Ja", "correct": true, "because": "Zukünftiges Ich profitiert"}, {"text": "Nein", "correct": false, "because": "Langfristig hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Kommentare entscheidend?', 4, '[{"text": "Verständlichkeit", "correct": true, "because": "Fördert Lesbarkeit"}, {"text": "Viel Text", "correct": false, "because": "Kürze besser"}, {"text": "Zeitstempel", "correct": false, "because": "Git reicht"}]');
